//! `cargo xtask kernel-index [--check]`: a one-page map of the libm fast-tier kernels
//! (LIBM-KERNEL-INDEX), so a libm story learns what exists without reading the kernel code.
//!
//! Sources: every `crates/math/src/fast*.rs` and every `.rs` under a `crates/math/src/fast*/`
//! directory except `tests.rs`. Output: `crates/math/KERNELS.md` (`@generated`), one line per
//! function (any visibility) outside test code, with its file and line, its signature, the tagged
//! lines of its doc comment and the doc comment's first sentence; macro invocations that define
//! entries (`fast_fn!(...)` and the like) are collapsed to one line per run of the same macro.
//!
//! Doc tags (one rule): a doc line that starts with `bound:`, `domain:` or `declines:` is
//! printed as is. A function without a `bound:` line prints `bound: undocumented`; the index
//! never derives a bound from prose.
//!
//! `--check` (run by `cargo xtask tables --check`, so by static's `tables-fresh`) fails when the
//! file is missing or differs from what the sources give, but only on the CI train
//! (`LIELLA_TRAIN=1`): the file is train-owned (RECORDS), so a story branch never commits it and
//! gets one advisory line instead, the same rule as `records::fresh_check`.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

const OUT: &str = "crates/math/KERNELS.md";
const SRC: &str = "crates/math/src";
const TAGS: [&str; 3] = ["bound:", "domain:", "declines:"];
const SUMMARY_MAX: usize = 160;

pub fn run(root: &Path, check: bool) -> Result<(), String> {
    let text = generate(root)?;
    let out = root.join(OUT);
    let old = std::fs::read_to_string(&out).ok();
    if check && !on_train() {
        let pending = old.as_deref() != Some(text.as_str());
        println!("kernel-index: {OUT} {}", if pending { "pending regeneration by the train" } else { "up to date" });
        return Ok(());
    }
    if check {
        return match old {
            Some(o) if o == text => {
                println!("kernel-index: up to date ({OUT})");
                Ok(())
            }
            Some(_) => Err(format!("{OUT} is out of date: run `cargo xtask kernel-index` (or `cargo xtask tables`)")),
            None => Err(format!("{OUT} is missing: run `cargo xtask kernel-index` (or `cargo xtask tables`)")),
        };
    }
    if old.as_deref() != Some(text.as_str()) {
        std::fs::write(&out, &text).map_err(|e| format!("{OUT}: {e}"))?;
        println!("kernel-index: wrote {OUT}");
    } else {
        println!("kernel-index: {OUT} unchanged");
    }
    Ok(())
}

/// The CI train's gate (`LIELLA_TRAIN=1`), where a stale train-owned file is fatal.
fn on_train() -> bool {
    std::env::var("LIELLA_TRAIN").is_ok_and(|v| v == "1")
}

/// The source files, sorted by path relative to `crates/math/src`.
fn sources(root: &Path) -> Result<Vec<PathBuf>, String> {
    let dir = root.join(SRC);
    let mut files = Vec::new();
    for e in std::fs::read_dir(&dir).map_err(|e| format!("{SRC}: {e}"))?.flatten() {
        let p = e.path();
        let name = e.file_name().to_string_lossy().into_owned();
        if !name.starts_with("fast") {
            continue;
        }
        if p.is_dir() {
            for f in std::fs::read_dir(&p).map_err(|e| format!("{}: {e}", p.display()))?.flatten() {
                let fp = f.path();
                if fp.extension().is_some_and(|x| x == "rs") && f.file_name() != "tests.rs" {
                    files.push(fp);
                }
            }
        } else if name.ends_with(".rs") {
            files.push(p);
        }
    }
    files.sort();
    Ok(files)
}

fn generate(root: &Path) -> Result<String, String> {
    let mut s = String::new();
    s.push_str("<!-- @generated by cargo xtask kernel-index (xtask/src/kernel_index.rs) from crates/math/src/fast*.rs and crates/math/src/fast*/ (tests excluded). Do not edit or commit: the CI train regenerates it; run `cargo xtask kernel-index` to read it locally. -->\n");
    s.push_str("# libm fast-tier kernels: index\n\n");
    s.push_str("Read this first; open kernel code only by range (`file:line` below) for the functions you change.\n");
    s.push_str("Each line: `file:line`, signature, the doc comment's tagged lines (`bound:`, `domain:`, `declines:`;\n");
    s.push_str("`bound: undocumented` when the doc has no `bound:` line) and its first sentence.\n");
    for path in sources(root)? {
        let rel = path.strip_prefix(root.join(SRC)).map_err(|e| e.to_string())?.to_string_lossy().replace('\\', "/");
        let text = std::fs::read_to_string(&path).map_err(|e| format!("{rel}: {e}"))?;
        let _ = write!(s, "\n## {rel} ({})\n\n", family(&rel));
        let lines = index_file(&rel, &text);
        if lines.is_empty() {
            s.push_str("(no functions)\n");
        }
        for line in lines {
            s.push_str(&line);
            s.push('\n');
        }
    }
    Ok(s)
}

/// `f32 exp_log` for `fast32/exp_log.rs`, `f32 core` for `fast32.rs`, `f64` for `fast64.rs`.
fn family(rel: &str) -> String {
    let stem = rel.trim_end_matches(".rs");
    let (top, sub) = stem.split_once('/').map_or((stem, None), |(a, b)| (a, Some(b)));
    let width = top.trim_start_matches("fast");
    let width = if width.chars().all(|c| c.is_ascii_digit()) && !width.is_empty() { format!("f{width}") } else { top.to_string() };
    match sub {
        Some(f) => format!("{width} {f}"),
        None if top == "fast32" => format!("{width} core"),
        None => width,
    }
}

fn indent(l: &str) -> usize {
    l.len() - l.trim_start().len()
}

/// Is `t` (trimmed) the start of a function item? Returns the text from `fn` on, with the
/// visibility kept.
fn fn_start(t: &str) -> Option<&str> {
    let mut rest = t;
    for p in ["pub(crate) ", "pub(super) ", "pub(self) ", "pub "] {
        if let Some(r) = rest.strip_prefix(p) {
            rest = r;
            break;
        }
    }
    for q in ["const ", "unsafe ", "extern \"C\" "] {
        rest = rest.strip_prefix(q).unwrap_or(rest);
    }
    rest.starts_with("fn ").then_some(t)
}

/// The macro name of an item-position invocation such as `fast_fn!(exp, Fast::Exp);`.
fn invocation(t: &str) -> Option<(&str, &str)> {
    let (name, rest) = t.split_once("!(")?;
    if name.is_empty() || !name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') || name == "macro_rules" {
        return None;
    }
    let first = rest.split([',', ')']).next().unwrap_or("").trim();
    Some((name, first))
}

fn summary(doc: &[String]) -> String {
    let mut para = String::new();
    for d in doc {
        if d.is_empty() {
            break;
        }
        if !para.is_empty() {
            para.push(' ');
        }
        para.push_str(d);
    }
    let end = para.find(". ").map_or(para.len(), |i| i + 1);
    let mut out: String = para[..end].to_string();
    if out.chars().count() > SUMMARY_MAX {
        out = out.chars().take(SUMMARY_MAX).collect::<String>() + "…";
    }
    out
}

fn index_file(rel: &str, text: &str) -> Vec<String> {
    let lines: Vec<&str> = text.lines().collect();
    let mut out = Vec::new();
    let mut doc: Vec<String> = Vec::new();
    let mut test_attr = false;
    let mut run: Option<(String, usize, usize, Vec<String>)> = None; // macro, first line, last line, first args
    let flush = |run: &mut Option<(String, usize, usize, Vec<String>)>, out: &mut Vec<String>| {
        if let Some((m, a, b, names)) = run.take() {
            let at = if a == b { format!("{rel}:{a}") } else { format!("{rel}:{a}-{b}") };
            out.push(format!("- `{at}` `{m}!` entries: {}", names.join(", ")));
        }
    };
    let mut i = 0;
    while i < lines.len() {
        let l = lines[i];
        let t = l.trim();
        let n = i + 1;
        if let Some(d) = t.strip_prefix("///") {
            doc.push(d.strip_prefix(' ').unwrap_or(d).trim_end().to_string());
            i += 1;
            continue;
        }
        if t.starts_with("#[") || t.starts_with("$(#[") || (t.starts_with("//") && !t.starts_with("//!")) {
            test_attr |= t.starts_with("#[cfg(test)]");
            i += 1;
            continue;
        }
        if t.is_empty() {
            doc.clear();
            test_attr = false;
            i += 1;
            continue;
        }
        if let Some((m, first)) = invocation(t).filter(|_| !t.contains('$')) {
            match &mut run {
                Some((rm, _, b, names)) if *rm == m && *b + 1 == n => {
                    *b = n;
                    names.push(first.to_string());
                }
                _ if !first.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') => {
                    // Not an entry list (e.g. `kernels!(<attributes>; ...)`): the invocation as written.
                    flush(&mut run, &mut out);
                    out.push(format!("- `{rel}:{n}` `{t}`"));
                }
                _ => {
                    flush(&mut run, &mut out);
                    run = Some((m.to_string(), n, n, vec![first.to_string()]));
                }
            }
            doc.clear();
            test_attr = false;
            i += 1;
            continue;
        }
        flush(&mut run, &mut out);
        // A test-only module with a body: skip to its closing brace.
        if test_attr && (t.starts_with("mod ") || t.starts_with("pub mod ")) && t.ends_with('{') {
            let close = format!("{}}}", " ".repeat(indent(l)));
            while i < lines.len() && lines[i].trim_end() != close {
                i += 1;
            }
            doc.clear();
            test_attr = false;
            i += 1;
            continue;
        }
        if let Some(start) = fn_start(t).filter(|_| !t.contains('$') && !test_attr) {
            let mut sig = start.to_string();
            let mut j = i;
            while !(sig.ends_with('{') || sig.ends_with(';')) && j + 1 < lines.len() {
                j += 1;
                sig.push(' ');
                sig.push_str(lines[j].trim());
            }
            let sig = sig.trim_end_matches(['{', ';']).trim_end().to_string();
            let mut fields = vec![format!("- `{rel}:{n}` `{sig}`")];
            let tags: Vec<&String> = doc.iter().filter(|d| TAGS.iter().any(|g| d.starts_with(g))).collect();
            if !tags.iter().any(|d| d.starts_with("bound:")) {
                fields.push("bound: undocumented".into());
            }
            fields.extend(tags.iter().map(|d| d.to_string()));
            let sum = summary(&doc);
            if !sum.is_empty() {
                fields.push(format!("doc: {sum}"));
            }
            out.push(fields.join(" — "));
        }
        doc.clear();
        test_attr = false;
        i += 1;
    }
    flush(&mut run, &mut out);
    out
}
